import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"REST API","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-chefs-embed/developer/rest-api.md","filePath":"content/plugins/bcew-chefs-embed/developer/rest-api.md"}`),a={name:`content/plugins/bcew-chefs-embed/developer/rest-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to “REST API”">​</a></h1><p>The plugin registers routes under <code>/wp-json/bcew-chefs-embed/v1</code>.</p><h2 id="get-saved-forms" tabindex="-1">Get saved forms <a class="header-anchor" href="#get-saved-forms" aria-label="Permalink to “Get saved forms”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /wp-json/bcew-chefs-embed/v1/forms</span></span></code></pre></div><p>The block editor uses this route to populate its form-title selector. It requires the current user to have the <code>edit_posts</code> capability and returns saved form titles plus their IDs. Unauthorized requests receive a <code>403</code> response.</p><p>The route is registered in <code>bcew-chefs-embed.php</code> and handled by <code>bcew_chefs_embed_get_saved_forms()</code>.</p><h2 id="get-embed-configuration" tabindex="-1">Get embed configuration <a class="header-anchor" href="#get-embed-configuration" aria-label="Permalink to “Get embed configuration”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /wp-json/bcew-chefs-embed/v1/embed-config?formId=&lt;form-id&gt;</span></span></code></pre></div><p>The editor preview and published frontend use this route. It is public because an anonymous visitor must be able to load a published form. The route:</p><ol><li>Looks up the configured Form ID.</li><li>Decrypts its stored API key on the server.</li><li>Sends a server-to-server Basic Authentication request to CHEFS.</li><li>Returns the short-lived token, CHEFS base URL, and configured confirmation message.</li></ol><p>The API key is not included in the response. Omitting the required <code>formId</code> parameter returns <code>400</code>; an unknown or undecryptable Form ID returns <code>404</code>. Failures contacting CHEFS or invalid CHEFS responses return an error response from the gateway/authentication path.</p><p>The route is registered and handled by <code>src/EmbedConfigController.php</code>.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};